/* ==========================================================================
   USER CUSTOM CASE SYSTEM & EDITOR
   ========================================================================== */
function getUserCasesKey(){
  return profile ? ("cs2-user-cases:" + profile) : "cs2-user-cases";
}

function getDefaultSampleCase(){
  // Tìm một số skin tuyệt đẹp để làm hòm mẫu mặc định
  const sampleNames = ["AWP | Dragon Lore", "AK-47 | Asiimov", "M4A4 | Howl", "Butterfly Knife | Doppler", "Sport Gloves | Vice", "Desert Eagle | Printstream"];
  const indices = [];
  sampleNames.forEach(name => {
    const idx = ITEMS.findIndex(it => it.n === name);
    if(idx >= 0) indices.push(idx);
  });
  if(indices.length < 2){
    indices.push(0, 1, 2, 3);
  }
  return {
    id: "ucc-sample-1",
    name: "Hòm Mẫu: Huyền Thoại CS2",
    desc: "Hòm mẫu gồm AWP Dragon Lore, AK Asiimov, Dao Butterfly Doppler và Găng Vice",
    tag: "Mẫu VIP",
    color: "#ff6b00",
    crateStyle: "Kilowatt Case",
    priceMode: "auto",
    fixedPrice: 25,
    items: indices,
    updatedAt: Date.now()
  };
}

function getUserCasesRaw(){
  try{
    const k = getUserCasesKey();
    let d = JSON.parse(localStorage.getItem(k));
    if((!d || !d.length) && profile){
      const g = JSON.parse(localStorage.getItem("cs2-user-cases"));
      if(g && g.length){
        d = g;
        localStorage.setItem(k, JSON.stringify(d));
      }
    }
    if(!d || !Array.isArray(d) || !d.length){
      // Khởi tạo hòm mẫu đầu tiên
      const sample = getDefaultSampleCase();
      d = [sample];
      localStorage.setItem(k, JSON.stringify(d));
    }
    return Array.isArray(d) ? d : [];
  }catch(e){
    return [getDefaultSampleCase()];
  }
}

function saveUserCasesRaw(list){
  try{
    localStorage.setItem(getUserCasesKey(), JSON.stringify(list));
    if(!profile) localStorage.setItem("cs2-user-cases", JSON.stringify(list));
  }catch(e){}
}

function buildUserCase(raw){
  const items = (raw.items || []).map(idx => ITEMS[idx]).filter(Boolean);
  const pool = items.map(it => ({
    base: it,
    v: typicalPrice(it)
  })).filter(t => t.v > 0);
  if(!pool.length){
    pool.push({ base: ITEMS[0], v: typicalPrice(ITEMS[0]) });
  }
  pool.forEach(t => { t.w = Math.pow(t.v, -0.9); });
  const totalW = sum(pool, t => t.w);
  pool.forEach(t => { t.pct = t.w / (totalW || 1); });
  pool.sort((a, b) => b.v - a.v);
  const ev = sum(pool, t => t.pct * t.v);
  const autoPrice = Math.max(0.2, Math.round((ev / 0.9) * 100) / 100);
  const price = (raw.priceMode === "fixed" && raw.fixedPrice > 0) ? Number(raw.fixedPrice) : autoPrice;
  const rCase = OFFICIAL.find(t => t.name === raw.crateStyle) || OFFICIAL[0];
  const featItem = pool[0]?.base?.img || ITEMS[0].img;
  return {
    id: raw.id,
    name: raw.name || "Hòm Tự Tạo",
    desc: raw.desc || "Hòm do người chơi tự thiết kế",
    tag: raw.tag || "Tự tạo",
    color: raw.color || "#ff6b00",
    custom: true,
    userCreated: true,
    pool: pool,
    price: price,
    image: rCase.image,
    feat: featItem,
    hue: Math.round(hexHue(raw.color || "#ff6b00") - 28),
    raw: raw
  };
}

function getUserCases(){
  return getUserCasesRaw().map(buildUserCase);
}

// Editor State
let ceEditingId = null;
let ceSelected = new Set();

function initCustomCaseEditor(){
  const selCrate = $("#ce-crate-style");
  if(selCrate && !selCrate.children.length){
    OFFICIAL.forEach(c => {
      const opt = document.createElement("option");
      opt.value = c.name;
      opt.textContent = c.name;
      selCrate.appendChild(opt);
    });
  }

  const priceMode = $("#ce-price-mode");
  const fixedInput = $("#ce-fixed-price");
  if(priceMode && fixedInput){
    priceMode.onchange = () => {
      fixedInput.disabled = (priceMode.value === "auto");
    };
  }

  const colorInput = $("#ce-color");
  const colorText = $("#ce-color-text");
  if(colorInput && colorText){
    colorInput.oninput = () => {
      colorText.textContent = colorInput.value;
    };
  }

  const searchInput = $("#ce-search");
  const filterCat = $("#ce-filter-cat");
  const filterRarity = $("#ce-filter-rarity");
  if(searchInput) searchInput.oninput = () => ceRenderCatalog();
  if(filterCat) filterCat.onchange = () => ceRenderCatalog();
  if(filterRarity) filterRarity.onchange = () => ceRenderCatalog();

  const clearBtn = $("#ce-btn-clear");
  if(clearBtn){
    clearBtn.onclick = () => {
      ceSelected.clear();
      ceUpdateSelected();
      ceRenderCatalog();
    };
  }

  const saveBtn = $("#ce-btn-save");
  if(saveBtn){
    saveBtn.onclick = () => ceSaveCase();
  }

  // Presets
  $$(".ce-preset-btn").forEach(btn => {
    btn.onclick = () => {
      const preset = btn.dataset.preset;
      ceApplyPreset(preset);
    };
  });

  // Global triggers
  const btnCreate = $("#btn-create-custom-case");
  const btnCreateFirst = $("#btn-create-first-case");
  if(btnCreate) btnCreate.onclick = () => openCustomCaseEditor();
  if(btnCreateFirst) btnCreateFirst.onclick = () => openCustomCaseEditor();

  const btnImport = $("#btn-import-custom-case");
  if(btnImport){
    btnImport.onclick = () => ceImportCase();
  }

  // Case card action delegation
  document.addEventListener("click", ev => {
    const editBtn = ev.target.closest("[data-edit-ucc]");
    const delBtn = ev.target.closest("[data-del-ucc]");
    const shareBtn = ev.target.closest("[data-share-ucc]");

    if(editBtn){
      ev.stopPropagation();
      openCustomCaseEditor(editBtn.dataset.editUcc);
    } else if(delBtn){
      ev.stopPropagation();
      const id = delBtn.dataset.delUcc;
      if(confirm("Bạn có chắc chắn muốn xóa hòm tự tạo này không?")){
        let list = getUserCasesRaw().filter(c => c.id !== id);
        saveUserCasesRaw(list);
        renderCases();
        toast("Đã xóa hòm thành công!");
      }
    } else if(shareBtn){
      ev.stopPropagation();
      const id = shareBtn.dataset.shareUcc;
      const raw = getUserCasesRaw().find(c => c.id === id);
      if(raw){
        try{
          const code = "UCC:" + btoa(unescape(encodeURIComponent(JSON.stringify(raw))));
          copyText(code, "Đã sao chép mã hòm! Gửi mã này cho bạn bè để họ mở hòm của bạn.");
        }catch(e){
          toast("Không tạo được mã chia sẻ!");
        }
      }
    }
  });
}

function ceApplyPreset(type){
  let itemsToAdd = [];
  if(type === "knives"){
    itemsToAdd = ITEMS.map((it, idx) => ({ it, idx })).filter(x => x.it.cat === "Knives").slice(0, 12);
  } else if(type === "gloves"){
    itemsToAdd = ITEMS.map((it, idx) => ({ it, idx })).filter(x => x.it.cat === "Gloves").slice(0, 12);
  } else if(type === "asiimov"){
    itemsToAdd = ITEMS.map((it, idx) => ({ it, idx })).filter(x => /Asiimov/.test(x.it.n));
  } else if(type === "ak47"){
    itemsToAdd = ITEMS.map((it, idx) => ({ it, idx })).filter(x => x.it.w === "AK-47" && (x.it.r >= 3)).slice(0, 10);
  } else if(type === "awp"){
    itemsToAdd = ITEMS.map((it, idx) => ({ it, idx })).filter(x => x.it.w === "AWP" && (x.it.r >= 3)).slice(0, 10);
  }
  itemsToAdd.forEach(x => ceSelected.add(x.idx));
  ceUpdateSelected();
  ceRenderCatalog();
  toast(`Đã thêm ${itemsToAdd.length} món từ bộ sưu tập!`);
}

function ceRenderCatalog(){
  const grid = $("#ce-catalog-grid");
  if(!grid) return;
  grid.innerHTML = "";
  const search = ($("#ce-search")?.value || "").trim().toLowerCase();
  const cat = $("#ce-filter-cat")?.value || "all";
  const rarity = $("#ce-filter-rarity")?.value || "all";

  let filtered = [];
  for(let i = 0; i < ITEMS.length; i++){
    const it = ITEMS[i];
    if(cat !== "all" && it.cat !== cat) continue;
    if(rarity !== "all" && it.r !== Number(rarity)) continue;
    if(search && !it.n.toLowerCase().includes(search) && !(it.w || "").toLowerCase().includes(search)) continue;
    filtered.push({ it, idx: i });
    if(filtered.length >= 120) break; // giới hạn 120 món cho mượt DOM
  }

  filtered.forEach(({ it, idx }) => {
    const card = document.createElement("div");
    card.className = "ce-catalog-card" + (ceSelected.has(idx) ? " selected" : "");
    card.style.setProperty("--rc", RARITY[it.r]?.color || "#4b69ff");
    card.innerHTML = `
      <img src="${it.img}" alt="" loading="lazy" />
      <div class="n" title="${it.n}">${it.n}</div>
      <div class="p">${fmtUSD(typicalPrice(it))}</div>
    `;
    card.onclick = () => {
      if(ceSelected.has(idx)){
        ceSelected.delete(idx);
      } else {
        ceSelected.add(idx);
      }
      card.classList.toggle("selected", ceSelected.has(idx));
      ceUpdateSelected();
    };
    grid.appendChild(card);
  });
}

function ceUpdateSelected(){
  const countEl = $("#ce-selected-count");
  if(countEl) countEl.textContent = ceSelected.size;

  const tray = $("#ce-selected-grid");
  const emptyMsg = $("#ce-selected-empty-msg");
  if(!tray) return;

  tray.innerHTML = "";
  if(ceSelected.size === 0){
    if(emptyMsg) emptyMsg.hidden = false;
    tray.appendChild(emptyMsg || document.createTextNode("Chưa chọn skin nào."));
  } else {
    if(emptyMsg) emptyMsg.hidden = true;
    [...ceSelected].forEach(idx => {
      const it = ITEMS[idx];
      if(!it) return;
      const chip = document.createElement("div");
      chip.className = "ce-selected-chip";
      chip.style.setProperty("--rc", RARITY[it.r]?.color || "#ffd700");
      chip.innerHTML = `
        <button type="button" class="del-btn" title="Xóa món này">×</button>
        <img src="${it.img}" alt="" />
        <div class="n" title="${it.n}">${it.n}</div>
        <div class="p">${fmtUSD(typicalPrice(it))}</div>
      `;
      chip.querySelector(".del-btn").onclick = (ev) => {
        ev.stopPropagation();
        ceSelected.delete(idx);
        ceUpdateSelected();
        ceRenderCatalog();
      };
      tray.appendChild(chip);
    });
  }

  // Cập nhật stats
  const pList = [...ceSelected].map(i => typicalPrice(ITEMS[i])).filter(v => v > 0);
  let ev = 0, recPrice = 0;
  if(pList.length){
    const weights = pList.map(v => Math.pow(v, -0.9));
    const totW = sum(weights);
    ev = sum(pList.map((v, i) => (weights[i] / (totW || 1)) * v));
    recPrice = Math.max(0.2, Math.round((ev / 0.9) * 100) / 100);
  }
  const statsEl = $("#ce-selected-stats");
  if(statsEl){
    statsEl.textContent = `Cần tối thiểu 2 món. Tổng giá trị TB (EV): ${fmtUSD(ev)} · Giá hòm khuyến nghị: ${fmtUSD(recPrice)}`;
  }
  if($("#ce-price-mode")?.value === "auto" && $("#ce-fixed-price")){
    $("#ce-fixed-price").value = recPrice;
  }
}

function openCustomCaseEditor(editId = null){
  ceEditingId = editId;
  const nameInput = $("#ce-name");
  const descInput = $("#ce-desc");
  const crateSelect = $("#ce-crate-style");
  const colorInput = $("#ce-color");
  const colorText = $("#ce-color-text");
  const priceMode = $("#ce-price-mode");
  const fixedInput = $("#ce-fixed-price");

  if(editId){
    const raw = getUserCasesRaw().find(c => c.id === editId);
    if(raw){
      if(nameInput) nameInput.value = raw.name || "";
      if(descInput) descInput.value = raw.desc || "";
      if(crateSelect) crateSelect.value = raw.crateStyle || OFFICIAL[0].name;
      if(colorInput) colorInput.value = raw.color || "#ff6b00";
      if(colorText) colorText.textContent = raw.color || "#ff6b00";
      if(priceMode) priceMode.value = raw.priceMode || "auto";
      if(fixedInput){
        fixedInput.value = raw.fixedPrice || 10;
        fixedInput.disabled = (raw.priceMode === "auto");
      }
      ceSelected = new Set(raw.items || []);
    }
  } else {
    // Tạo mới
    if(nameInput) nameInput.value = "";
    if(descInput) descInput.value = "";
    if(crateSelect && crateSelect.options.length) crateSelect.selectedIndex = 0;
    if(colorInput) colorInput.value = "#ff6b00";
    if(colorText) colorText.textContent = "#ff6b00";
    if(priceMode) priceMode.value = "auto";
    if(fixedInput){
      fixedInput.value = 10;
      fixedInput.disabled = true;
    }
    ceSelected = new Set();
  }

  ceUpdateSelected();
  ceRenderCatalog();
  openModal("#modal-case-editor");
}

function ceSaveCase(){
  const name = ($("#ce-name")?.value || "").trim();
  if(!name){
    toast("Vui lòng nhập tên cho hòm!");
    $("#ce-name")?.focus();
    return;
  }
  if(ceSelected.size < 2){
    toast("Hãy chọn ít nhất 2 món đồ để tạo hòm!");
    return;
  }

  const raw = {
    id: ceEditingId || ("ucc-" + Date.now()),
    name: name,
    desc: ($("#ce-desc")?.value || "").trim() || "Hòm tùy chỉnh cá nhân",
    tag: "Tự tạo",
    color: $("#ce-color")?.value || "#ff6b00",
    crateStyle: $("#ce-crate-style")?.value || OFFICIAL[0].name,
    priceMode: $("#ce-price-mode")?.value || "auto",
    fixedPrice: Number($("#ce-fixed-price")?.value) || 5,
    items: [...ceSelected],
    updatedAt: Date.now()
  };

  let list = getUserCasesRaw();
  const existingIdx = list.findIndex(c => c.id === raw.id);
  if(existingIdx >= 0){
    list[existingIdx] = raw;
  } else {
    list.unshift(raw);
  }

  saveUserCasesRaw(list);
  closeModal("#modal-case-editor");
  renderCases();
  toast(`🎉 Đã lưu hòm "${raw.name}" thành công! Bạn có thể mở ngay bây giờ.`);
}

function ceImportCase(){
  const code = prompt("Dán mã hòm (bắt đầu bằng UCC:) mà bạn bè chia sẻ vào đây:");
  if(!code || !code.trim()) return;
  try{
    let s = code.trim();
    if(s.startsWith("UCC:")) s = s.slice(4);
    const raw = JSON.parse(decodeURIComponent(escape(atob(s))));
    if(raw && raw.name && Array.isArray(raw.items) && raw.items.length >= 2){
      raw.id = "ucc-" + Date.now();
      raw.name = raw.name + " (Nhập)";
      let list = getUserCasesRaw();
      list.unshift(raw);
      saveUserCasesRaw(list);
      renderCases();
      toast(`🎉 Đã nhập thành công hòm "${raw.name}"!`);
    } else {
      toast("Mã hòm không đúng định dạng hoặc có ít hơn 2 món đồ!");
    }
  }catch(err){
    toast("Lỗi đọc mã hòm! Vui lòng kiểm tra lại mã đã sao chép.");
  }
}

// Khởi tạo Custom Case Editor và render danh sách hòm
initCustomCaseEditor();
renderCases("");
